    candidates = []
    for axis in ('vertical', 'horizontal'):
        if axis == 'horizontal':
            first, last = runs(grid[0]), runs(grid[-1])
        else:
            first = runs([grid[r][0] for r in range(h)])
            last = runs([grid[r][-1] for r in range(h)])
        for a, b in ((a, b) for a in first for b in last):
            if a[1] - a[0] == b[1] - b[0] and a[2] == b[2]:
                candidates.append((a[1]-a[0], axis, a, b))
    if not candidates:
        return out
    preferred = [item for item in candidates if item[1] == 'vertical']
    if preferred:
        candidates = preferred
    _, axis, first, last = max(candidates)
    a0, a1, bar_color = first
    b0, b1, _ = last

    if axis == 'horizontal':
